#define CH32RV_TIMER_ITR { {1, 0, 2}, {2, 0, 1}, {3, 0, 1}, {3, 1, 2} }

/* ---- ADC regular group's timer sources (device-data adc_triggers.csv): X(timer, event (0 TRGO, n CCn), EXTSEL value), tried in this order ---- */
